/* ===================================================================================== */
/* Pluggable Authentication Providers */
/* ===================================================================================== */
/* Introduces the AuthenticationProvider table, the metadata catalog of authentication */
/* providers (Auth0, Okta, MSAL, Cognito, Google, WorkOS, or any third-party driver). */
/* This makes auth providers METADATA-DRIVEN like the rest of MemberJunction: a row names */
/* a DriverClass that is resolved at runtime via */
/*   MJGlobal.ClassFactory.CreateInstance(BaseAuthProvider, DriverClass, config) */
/* exactly as File Storage Providers (ServerDriverKey) and AI Remote Browser Providers */
/* (DriverClass) already work. No more hard-wired provider lists: a third party plugs in */
/* by shipping a @RegisterClass(BaseAuthProvider,'x') subclass and adding a row here. */
/* The mj.config.cjs `authProviders[]` array remains a back-compat fallback when this */
/* table is empty, so no existing deployment has to change anything to keep booting. */
/* --------------------------------------------------------------------------------- */
/* WHY TWO CONFIGURATION JSON COLUMNS */
/* --------------------------------------------------------------------------------- */
/* The browser is PRE-AUTH when it needs to know which providers exist, so the server */
/* publishes a public catalog (GET /auth/providers) with no bearer token. That endpoint */
/* must never become a way to read secrets that an administrator pasted into a config */
/* blob, so the split is enforced by the SCHEMA rather than by reviewer vigilance: */
/*   AdditionalConfiguration -- SERVER-SIDE ONLY. Never published. Driver-specific extras */
/*                              consumed by the server provider during token validation. */
/*   ClientConfiguration     -- PUBLISHED VERBATIM to the pre-auth catalog. Anything the */
/*                              browser SDK needs (redirectUri, apiHostname, ...). Treat */
/*                              every value here as world-readable. */
/* A single merged blob would mean the publish path had to guess which keys were safe. */
/* With two columns the public projection is a fixed allow-list of columns and the */
/* question "could this leak?" is answered by which column the value sits in. */
/* --------------------------------------------------------------------------------- */
/* SECRETS */
/* --------------------------------------------------------------------------------- */
/* Most providers validate via PUBLIC JWKS and need NO secret (CredentialID null, which */
/* is the case for every provider MJ ships today -- Auth0, Okta, MSAL, Cognito, Google, */
/* WorkOS). Providers that DO need server-side secret material (confidential-client */
/* OAuth, management APIs, SCIM) reference the existing Credential table via */
/* CredentialID and are decrypted at runtime by CredentialEngine -- mirroring the File */
/* Storage credential model. Secrets are never stored on this table. */
/* CodeGen handoff: after this migration runs, `mj codegen` generates */
/*   - MJAuthenticationProviderEntity (entity name "MJ: Authentication Providers") */
/*   - the base view + spCreate/spUpdate/spDelete + permissions */
/* which AuthProviderEngine / the catalog endpoint / the login picker build against. */
/* ===================================================================================== */
CREATE TABLE __mj."AuthenticationProvider" (
  "ID" UUID NOT NULL DEFAULT (
    GEN_RANDOM_UUID()
  ),
  "Name" /* Identity / discovery */ VARCHAR(100) NOT NULL,
  "Description" TEXT NULL,
  "DriverClass" VARCHAR(255) NOT NULL,
  "Issuer" /* OIDC / JWT connection fields (non-secret; used by BaseAuthProvider for validation) */ VARCHAR(500) NULL,
  "Audience" VARCHAR(500) NULL,
  "JWKSUri" VARCHAR(500) NULL,
  "ClientID" VARCHAR(255) NULL,
  "Domain" VARCHAR(255) NULL,
  "Scopes" VARCHAR(500) NULL,
  "AdditionalConfiguration" /* Driver-specific configuration, split by trust boundary (see header) */ TEXT NULL,
  "ClientConfiguration" TEXT NULL,
  "CredentialID" /* Optional secret material for providers that make server-initiated calls */ UUID NULL,
  "Status" /* Lifecycle / selection */ VARCHAR(20) NOT NULL DEFAULT (
    'Active'
  ),
  "IsDefault" BOOLEAN NOT NULL DEFAULT FALSE,
  "ClientVisible" /* Browser login-picker presentation (picker renders only when 2+ Active, ClientVisible rows exist) */ BOOLEAN NOT NULL DEFAULT TRUE,
  "DisplayName" VARCHAR(100) NULL,
  "Icon" VARCHAR(100) NULL,
  "Sequence" INT NOT NULL DEFAULT (
    0
  ),
  CONSTRAINT "PK_AuthenticationProvider" PRIMARY KEY ("ID"),
  CONSTRAINT "UQ_AuthenticationProvider_Name" UNIQUE (
    "Name"
  ),
  CONSTRAINT "FK_AuthenticationProvider_Credential" FOREIGN KEY ("CredentialID") REFERENCES __mj."Credential" (
    "ID"
  ),
  CONSTRAINT "CK_AuthenticationProvider_Status" CHECK ("Status" IN ('Active', 'Inactive'))
);

COMMENT ON TABLE __mj."AuthenticationProvider" IS 'Metadata catalog of authentication providers. Each row defines one provider (Auth0, Okta, MSAL, Cognito, Google, WorkOS, or any third-party driver) whose implementation is resolved at runtime from DriverClass via MJGlobal.ClassFactory.CreateInstance(BaseAuthProvider, DriverClass). Supersedes the hard-wired mj.config.cjs authProviders array, which remains a back-compat fallback when this table is empty.';

COMMENT ON COLUMN __mj."AuthenticationProvider"."Name" IS 'Unique, human-readable name for this provider instance (e.g. "WorkOS Production", "Corporate Azure AD"). Also the key used to register the provider with AuthProviderFactory.';

COMMENT ON COLUMN __mj."AuthenticationProvider"."Description" IS 'Optional administrator notes describing this provider configuration.';

COMMENT ON COLUMN __mj."AuthenticationProvider"."DriverClass" IS 'Driver key resolved at runtime via MJGlobal.ClassFactory.CreateInstance(BaseAuthProvider, DriverClass). MUST match the @RegisterClass key on the concrete server provider (e.g. "workos", "auth0", "okta", "msal", "cognito", "google"). The browser resolves its matching MJAuthBase subclass from the same key, so a driver ships as a server/browser pair under one name.';

COMMENT ON COLUMN __mj."AuthenticationProvider"."Issuer" IS 'Expected JWT issuer (the "iss" claim). Used to route an incoming token to this provider and to validate the token. E.g. https://api.workos.com/user_management/<clientId>.';

COMMENT ON COLUMN __mj."AuthenticationProvider"."Audience" IS 'Expected JWT audience (the "aud" claim) enforced during validation.';

COMMENT ON COLUMN __mj."AuthenticationProvider"."JWKSUri" IS 'JWKS endpoint URL used to fetch the signing keys that verify token signatures. E.g. https://api.workos.com/sso/jwks/<clientId>.';

COMMENT ON COLUMN __mj."AuthenticationProvider"."ClientID" IS 'Public OAuth client ID. Safe to expose to the browser and published in the pre-auth provider catalog.';

COMMENT ON COLUMN __mj."AuthenticationProvider"."Domain" IS 'Provider domain where applicable (e.g. Auth0/Okta tenant domain). Optional; published in the pre-auth provider catalog.';

COMMENT ON COLUMN __mj."AuthenticationProvider"."Scopes" IS 'OAuth scopes to request, space-delimited (e.g. "openid profile email"). Published in the pre-auth provider catalog.';

COMMENT ON COLUMN __mj."AuthenticationProvider"."AdditionalConfiguration" IS 'SERVER-SIDE ONLY driver configuration as a JSON object, for fields not modeled as columns. NEVER published to the pre-auth catalog. Merged into the provider config when the server driver is instantiated. Put anything the browser must not read here.';

COMMENT ON COLUMN __mj."AuthenticationProvider"."ClientConfiguration" IS 'Browser driver configuration as a JSON object (e.g. WorkOS apiHostname, Cognito region/userPoolId, redirectUri). PUBLISHED VERBATIM in the unauthenticated pre-auth provider catalog, so every value here must be considered world-readable. Server-only settings belong in AdditionalConfiguration.';

COMMENT ON COLUMN __mj."AuthenticationProvider"."Status" IS 'Lifecycle status. Only Active providers are registered at startup and offered for login.';

COMMENT ON COLUMN __mj."AuthenticationProvider"."IsDefault" IS 'When true, this provider is the default selection -- pre-highlighted in the login picker, and used directly when it is the only Active, client-visible provider.';

COMMENT ON COLUMN __mj."AuthenticationProvider"."ClientVisible" IS 'When true, this provider appears in the browser pre-auth login picker and is included in the public catalog endpoint. Set false for providers that only validate machine-to-machine tokens and should never be offered as an interactive login.';

COMMENT ON COLUMN __mj."AuthenticationProvider"."DisplayName" IS 'Label shown on the login picker button (e.g. "Microsoft", rendered as "Continue with Microsoft"). Falls back to Name when null.';

COMMENT ON COLUMN __mj."AuthenticationProvider"."Icon" IS 'Icon for the login picker button -- a Font Awesome class (e.g. "fa-brands fa-microsoft") or a known brand-logo key the picker maps to a brand chip.';

COMMENT ON COLUMN __mj."AuthenticationProvider"."Sequence" IS 'Ordering of this provider within the login picker (ascending).';

